    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Konfigurácia nastavení celého systému: základná URL, zabezpečenie, predvolený jazyk, časové pásmo, predvolené hodnoty bodovania rizík a ďalšie.',
    'SettingsPreferencesDesc'             => 'Predvolené hodnoty a preferencie správania v rámci SimpleRisk: jazyk, časové pásmo, stavy auditu, požiadavky na mapovanie rizík, prepínače správania používateľského rozhrania a podobne.',
