    'SettingsBackupsDesc'                 => 'Nakonfigurujte uchovávanie záloh, plánovanie a odkazy na stiahnutie pre zálohy databázy SimpleRisk.',
    'SettingsSecurityDesc'                => 'Nastavenia overovania, relácie, politiky hesiel, základnej adresy URL a zabezpečenia rozhrania API.',
    'SettingsLoggingDesc'                 => 'Konfigurácia protokolovania ladenia a auditu: úrovne protokolovania, uchovávanie a umiestnenie súborov protokolov.',
    'HealthCheckDesc'                     => 'Diagnostika stavu systému: verzia PHP, rozšírenia, povolenia súborov, pripojenie k databáze, plán cron a aktivácie doplnkov Extra.',
    'AnnouncementsDesc'                   => 'Vytvárajte a spravujte bannerové oznámenia viditeľné pre všetkých používateľov.',
    'RegisterAndUpgradeDesc'              => 'Zaregistrujte si svoju inštaláciu SimpleRisk, zadajte alebo obnovte kľúč predplatného a spustite aktualizácie Core/Extra jedným kliknutím.',
    'QueueMonitorDesc'                    => 'Skontrolujte front úloh na pozadí: čakajúce, prebiehajúce a neúspešné úlohy.',
    'ExtrasDesc'                          => 'Aktivujte, deaktivujte a konfigurujte doplnky SimpleRisk Extras (platené doplnky).',
    'ArtificialIntelligenceExtraDesc'     => 'Doplnok Artificial Intelligence Extra poskytuje rozšírenú analýzu rizík (vrátane hodnotení FAIR) a prispôsobenú dokumentáciu.',
    'CustomizationExtraDesc'              => 'Doplnok Customization Extra umožňuje pridávať a odstraňovať rôzne typy polí a dynamicky vytvárať vlastné šablóny stránok.',
    'NotificationExtraDesc'               => 'Doplnok E-mailové upozornenia umožňuje SimpleRisk odosielať e-mailové upozornenia, keď sú riziká odoslané, upravené alebo sa s nimi inak pracuje. Tento doplnok je možné pridať aj ako plánovaný skript na odosielanie bežných pripomienok, keď sú riziká pripravené na kontrolu manažmentom. V produkte SimpleRisk Core sa bez tohto doplnku mimo samotného nástroja neodosielajú žiadne upozornenia.',
    'VulnerabilityManagementExtraDesc'    => 'Doplnok Vulnerability Management Extra umožňuje zákazníkom integrovať ich inštanciu SimpleRisk s nástrojmi Qualys, Tenable.io alebo Rapid7 Nexpose/InsightVM a importovať do SimpleRisk údaje o aktívach aj zraniteľnostiach. Potom si môžete vybrať, ktoré lokality chcete pokryť, určiť, ktoré skóre zraniteľností sa majú importovať, a vyhodnotiť, ktoré zraniteľnosti sa premenia na riziká, aby ste ich mohli sledovať.',
    'IncidentManagementExtraDesc'         => 'Modul Incident Management Extra je založený na príručke NIST 800-61 Computer Security Incident Handling Guide a poskytuje možnosti riadenia incidentov v rámci systému SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Premenujte terminológiu SimpleRisk (Riziko, Aktívum, Rámec atď.) v celom používateľskom rozhraní.',
    'RiskConfigurationDesc'               => 'Konfigurácia pravidiel bodovania rizík: úrovne, rizikový apetít, prahové hodnoty SLA a klasické vzorce rizika / vzorce rizika s prispievajúcimi faktormi.',
    'RiskAndThreatCatalogDesc'            => 'Spravujte katalóg hodnôt rizík a hrozieb používaných v rozbaľovacích zoznamoch.',
    'AddAndRemoveValuesDesc'              => 'Spravujte hodnoty rozbaľovacích zoznamov pre polia rizík: umiestnenie, zdroj, kategória, tím, technológia a ďalšie.',
    'AssetValuationDesc'                  => 'Nakonfigurujte stupnicu ocenenia aktív a prepísania ocenenia pre jednotlivé aktíva.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Pridávanie, úprava, deaktivácia a resetovanie používateľov; správa zásad hesiel.',
    'RoleManagementDesc'                  => 'Definujte roly a povolenia, ktoré každá rola udeľuje.',
    'TeamManagementDesc'                  => 'Vytvárajte a spravujte tímy používané na filtrovanie viditeľnosti záznamov.',
    'SeparationExtraDesc'                 => 'Doplnok oddelenia na základe tímu obmedzuje zobrazenie rizík iba na používateľov, ktorí sú členmi tímu, ktorému je riziko priradené. V produkte SimpleRisk Core bez tohto doplnku môže každý používateľ vidieť každé riziko.',
    'CustomAuthenticationExtraDesc'       => 'Doplnok Custom Authentication Extra poskytuje podporu pre overovanie v službe Active Directory a SAML. V produkte SimpleRisk Core je bez tohto doplnku jedinou možnosťou vytvoriť nových používateľov v úložisku identít SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Doplnok Encrypted Database Extra vygeneruje náhodný 256-bitový šifrovací kľúč AES a pomocou neho zašifruje citlivý text pred jeho vložením do databázy SimpleRisk. Tým sa zabráni komukoľvek zobraziť alebo upraviť údaje bez priameho použitia aplikácie SimpleRisk.',
    'OrganizationManagementDesc'          => 'Doplnok Organizational Hierarchy Extra umožňuje definovať viacero organizačných jednotiek, ktoré môžu zahŕňať ľubovoľný počet tímov. Používateľov je potom možné priradiť do jedného alebo viacerých tímov v rámci rôznych organizačných jednotiek. Ovplyvňuje to schopnosť používateľa zobraziť a používať tímy, používateľov a aktíva, s ktorými nie je súvisiaci.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Hromadne odstráňte riziká. Používajte striedmo – odstránenia sú trvalé.',
    'AuditTrailDesc'                      => 'Vyhľadávanie a exportovanie protokolu systémového auditu akcií používateľov.',
    'ImportExportExtraDesc'               => 'Doplnok Import-Export Extra umožňuje importovať údaje do SimpleRisk mapovaním polí v súbore CSV na polia v databáze SimpleRisk. Možno ho použiť na import výsledkov auditu z tabuľky tretej strany, výsledkov skenovania zraniteľností z iného nástroja, aktív z vašej CMDB a ďalšieho. Doplnok tiež umožňuje exportovať súbory CSV zo SimpleRisk obsahujúce riziká, zmiernenia, preskúmania alebo kombinovaný report všetkých troch.',
    'JiraExtraDesc'                       => 'Jira Integration Extra poskytuje používateľom možnosť obojsmernej integrácie s inštanciou Jira. Umožňuje prepojenie rizík s problémami Jira, ako aj synchronizáciu ich údajov, stavu a komentárov.',
    'APIExtraDesc'                        => 'Doplnok API Extra umožňuje zákazníkom používať rozhranie RESTful API na vytváranie skriptovaných interakcií s inými aplikáciami, aby dosiahli pokročilú automatizáciu a využili existujúcu infraštruktúru.',
    'AdvancedSearchExtraDesc'             => 'Doplnok Advanced Search Extra mení vyhľadávacie pole v hornej lište na jedno vyhľadávanie naprieč rizikami, rámcami, kontrolami, dokumentmi, výnimkami, testami, auditmi, aktívami a skupinami aktív, s plnohodnotnou stránkou vyhľadávania na prácu s výsledkami. Zobrazuje iba záznamy, ktoré smie používateľ vidieť.',
    'AssessmentsExtraDesc'                => 'Doplnok Risk Assessment Extra umožňuje používateľom definovať kontakty, vytvárať otázky (vrátane logiky), zostavovať viac otázok pomocou šablóny dotazníka, vytvárať dotazníky a odosielať ich kontaktom, zobraziť výsledky dotazníkov, pridávať riziká na základe týchto výsledkov, porovnávať výsledky v čase, importovať a exportovať externe prispôsobené hodnotenia a preskúmať stopu auditu hodnotenia rizík.',
    'ActiveAssessmentsDesc'               => 'Zobrazte a spravujte hodnotenia, ktoré sú momentálne rozpracované.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra poskytuje vizuálny, udalosťami riadený nástroj pracovných postupov, ktorý automatizuje akcie riadenia rizík v reakcii na udalosti v rámci SimpleRisk. Môžete navrhnúť pracovné postupy, ktoré sa spúšťajú pri zmenách – napríklad pri odoslaní, aktualizácii alebo kontrole rizika – na smerovanie schválení, priradenie práce a udržanie vášho procesu v chode bez manuálneho zásahu.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Rozšírenie Secure Controls Framework (SCF) Extra je priama integrácia medzi Secure Controls Framework a SimpleRisk. Importuje katalóg kontrol SCF a ich mapovania naprieč širokou škálou rámcov súladu a kybernetickej bezpečnosti do funkcie Governance v SimpleRisk, takže si môžete osvojiť rámce, ktoré potrebujete, a spravovať ich kontroly bez nutnosti vytvárať ich ručne.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migrujte staršie stĺpce dátumov preskúmania typu varchar na správne dátumové typy. Zobrazuje sa iba vtedy, keď je to potrebné.',
    'DatabaseUpgradeDesc'                 => 'Manuálne spustite rutinu aktualizácie databázy SimpleRisk.',

