    'EncryptionRestoreCtaHelp'              => 'Túto možnosť vyberte, ak overenie zistilo problémy a potrebujete sa vrátiť do stavu pred šifrovaním.',
    'EncryptionRestoreTitle'                => 'Obnoviť zo zálohy?',
    'EncryptionRestoreBodyWhy'              => 'Návrat k snímke pred šifrovaním, ktorá bola zachytená na začiatku poslednej aktivácie. Túto možnosť vyberte, ak overenie po aktivácii zistilo problémy a potrebujete zrušiť šifrovanie.',
    'EncryptionRestoreBodyWhat'             => 'Každý riadok zapísaný do databázy po vytvorení zálohy bude natrvalo stratený – vrátane rizík, zmierňujúcich opatrení, záznamov auditného logu a všetkých ďalších zmien vykonaných od aktivácie. Rozšírenie Šifrovaná databáza bude v rámci obnovenia deaktivované.',
    'EncryptionDeleteBackupCta'             => 'Odstrániť zálohu spred šifrovania',
    'EncryptionDeleteBackupCtaHelp'         => 'Vyberte túto možnosť po dokončení validácie po šifrovaní. Odstránením nešifrovanej snímky sa šifrovanie stáva skutočne ochranným.',
    'EncryptionDeleteBackupTitle'           => 'Odstrániť zálohu spred šifrovania?',
    'EncryptionDeleteBackupBodyWhy'         => 'Odstránenie nešifrovanej snímky údajov, ktorá bola zachytená na začiatku poslednej aktivácie. Jej neobmedzené uchovávanie marí účel šifrovania – kópiu pred šifrovaním si môže prečítať ktokoľvek s prístupom k databáze.',
    'EncryptionDeleteBackupBodyWhat'        => 'Záloha v databáze bude okamžite odstránená. Funkciu Obnoviť zo zálohy už nebudete môcť použiť na vrátenie databázy do stavu pred šifrovaním. Ak neskôr zistíte problémy so šifrovaním, jedinou možnosťou obnovy bude nové obnovenie databázy z vašich prevádzkových záloh.',
