    'EnableCSPHelp' => 'Content Security Policy (CSP) obmedzuje prehliadač tak, aby načítaval skripty, štýly, obrázky a písma iba zo samotného SimpleRisk, a blokuje vkladanie stránky do rámcov a odosielanie formulárov medzi rôznymi pôvodmi. Je to najsilnejšia vstavaná ochrana pred cross-site scriptingom. Ponechajte povolené, pokiaľ nie je v konflikte s proxy serverom, rozšírením prehliadača alebo integráciou tretej strany vo vašom prostredí.',
